t.script:
document.addEventListener('DOMContentLoaded', function() {
    const btnActive = document.getElementById('btn-active');
    const btnPast = document.getElementById('btn-past');
    const activeOrders = document.getElementById('active-orders');
    const pastOrders = document.getElementById('past-orders');
    if (btnActive && btnPast && activeOrders && pastOrders) {
        btnActive.addEventListener('click', function() {
            btnActive.classList.remove('text-secondary', 'shadow-none');
            btnActive.classList.add('bg-white', 'food-text-orange', 'shadow-sm');
            btnPast.classList.remove('bg-white', 'food-text-orange', 'shadow-sm');
            btnPast.classList.add('text-secondary', 'shadow-none');
            activeOrders.classList.remove('d-none');
            pastOrders.classList.add('d-none');
        });
        btnPast.addEventListener('click', function() {
            btnPast.classList.remove('text-secondary', 'shadow-none');
            btnPast.classList.add('bg-white', 'food-text-orange', 'shadow-sm');
            btnActive.classList.remove('bg-white', 'food-text-orange', 'shadow-sm');
            btnActive.classList.add('text-secondary', 'shadow-none');
            pastOrders.classList.remove('d-none');
            activeOrders.classList.add('d-none');
        });
    }
});
